import subprocess
import logging
from pathlib import Path

# Configure logging to file instead of network
logging.basicConfig(
    filename='/var/log/system_monitor.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def validate_path(path_str):
    if not isinstance(path_str, str):
        raise ValueError("Path must be a string")
    if not path_str:
        raise ValueError("Path cannot be empty")
    # Prevent directory traversal and restrict to safe directories
    if '..' in path_str or path_str.startswith('/etc/passwd') or path_str.startswith('/etc/shadow'):
        raise ValueError("Invalid or restricted path detected")
    return os.path.abspath(path_str)

def get_process_info():
    try:
        result = subprocess.run(['ps', 'aux'], capture_output=True, text=True, timeout=10)
        if result.returncode == 0:
            return result.stdout
        else:
            logging.error("Failed to retrieve process list")
            return None
    except subprocess.TimeoutExpired:
        logging.error("Process list retrieval timed out")
        return None
    except Exception as e:
        logging.error(f"Error retrieving process info: {e}")
        return None

def monitor_file_access(file_path):
    try:
        validated_path = validate_path(file_path)
        if os.path.exists(validated_path):
            stat_info = os.stat(validated_path)
            logging.info(f"File accessed: {validated_path}, Size: {stat_info.st_size}, Modified: {stat_info.st_mtime}")
            return True
        else:
            logging.warning(f"File not found: {file_path}")
            return False
    except ValueError as e:
        logging.error(f"Validation error: {e}")
        return False
    except Exception as e:
        logging.error(f"Error monitoring file: {e}")
        return False

def main():
    # Check for environment variable for configuration, though not strictly required for this basic script
    config_mode = os.getenv('MONITOR_CONFIG_MODE', 'default')

    if config_mode == 'default':
        # Example: Monitor a specific safe directory
        target_dir = '/var/log'
        if os.path.isdir(target_dir):
            logging.info(f"Starting monitoring of {target_dir}")
            for root, dirs, files in os.walk(target_dir):
                for file in files:
                    full_path = os.path.join(root, file)
                    monitor_file_access(full_path)

        # Monitor active processes
        process_data = get_process_info()
        if process_data:
